        public int version=2,trainingHp,trainingDamage,questStage,notes,chapter,chapterStage,attackCount,kills,crystals;public bool questComplete,returnedMemories,duelWon;public float spentMp,crystalBoost,splitDom;
        public List<string> met=new List<string>(),memories=new List<string>(),bosses=new List<string>();public List<RelicTimer> timers=new List<RelicTimer>();public List<RelicAlly> allies=new List<RelicAlly>();
