    public sealed partial class Simulation {
        public RpgProgress Rpg=new RpgProgress();public List<WorldRelic> WorldRelics=new List<WorldRelic>();public List<RelicField> RelicFields=new List<RelicField>();
        public static readonly string[] StatKeys={"str","agi","vit","int","spi","dex","fer","def","vamp","dom","aura","lck"};
        public static readonly V2 Home=new V2(750/64f,80-2210/64f),Altar=new V2(1830/64f,80-590/64f),Gate=new V2(3760/64f,80-2450/64f);
        string damageClass="skill";EnemyState incoming;bool exploding;V2 dashStart;float motion;bool aegis;int recoveryDepth;float hermesCooldown;
        public HeroQuestDef HeroQuest {get{return Array.Find(RpgCatalog.Quests,q=>q.hero==Hero.id);}}
        public QuestStep CurrentQuest {get{return Rpg.questStage<HeroQuest.steps.Length?HeroQuest.steps[Rpg.questStage]:null;}}
        public float AttackSpeed {get{return (1+Player.agi*.032f)*(Player.Has("haste")?1.16f:1)*(Timer("melon")>0?1.15f:1);}}
        public float CooldownReduction {get{return Math.Min(.45f,Player.spi*.025f);}}
        public float Recovery {get{return 1+Player.spi*.04f;}}
        public float Reach {get{return 1+Player.aura*.035f;}}
        public float Dominion {get{return 1+Player.dom*.055f;}}
        public float SummonHaste {get{return 1+Player.dom*.06f;}}
        public float SummonDuration {get{return 1+Player.dom*.04f;}}
        public float Omnivamp {get{return Player.vamp*.012f+(Player.Has("vampire")?.04f:0);}}
        public int Stat(string id){PlayerState p=Player;switch(id){case "str":return p.str;case "agi":return p.agi;case "vit":return p.vit;case "int":return p.intel;case "spi":return p.spi;case "dex":return p.dex;case "fer":return p.fer;case "def":return p.def;case "vamp":return p.vamp;case "dom":return p.dom;case "aura":return p.aura;case "lck":return p.lck;default:return 0;}}
        void SetStat(string id,int n){PlayerState p=Player;switch(id){case "str":p.str=n;break;case "agi":p.agi=n;break;case "vit":p.vit=n;break;case "int":p.intel=n;break;case "spi":p.spi=n;break;case "dex":p.dex=n;break;case "fer":p.fer=n;break;case "def":p.def=n;break;case "vamp":p.vamp=n;break;case "dom":p.dom=n;break;case "aura":p.aura=n;break;case "lck":p.lck=n;break;}}
        public void RecomputeStats(bool heal=true){PlayerState p=Player;float hp=p.maxHp,mp=p.maxMp;p.maxHp=Hero.hp+(p.level-1)*10+Rpg.trainingHp*25+p.vit*32+(p.Has("vitality")?65:0);p.maxMp=100+p.intel*20+(p.Has("spirit")?40:0);p.damage=Hero.damage+Rpg.trainingDamage*5;p.speed=(Hero.speed+p.agi*4.5f)/64*(p.Has("hermes")?1.18f:1)*(p.Has("haste")?1.12f:1);p.armor=Math.Min(.65f,p.def*.022f+(p.Has("vitality")?.06f:0));p.crit=Math.Min(1,.06f+p.dex*.025f+(p.Has("spirit")?.08f:0));if(heal){p.hp=Math.Min(p.maxHp,p.hp+Math.Max(0,p.maxHp-hp));p.mp=Math.Min(p.maxMp,p.mp+Math.Max(0,p.maxMp-mp));}else{p.hp=Math.Min(p.hp,p.maxHp);p.mp=Math.Min(p.mp,p.maxMp);}}
        public bool AllocateStat(string id){if(Array.IndexOf(StatKeys,id)<0||Player.statPoints<1||Stat(id)>=199)return false;SetStat(id,Stat(id)+1);Player.statPoints--;RecomputeStats();ScaleSummons(0);Emit("save","");return true;}
        public bool CanReset {get{return Zone(Player.position)=="village"||V2.Distance(Player.position,RpgCatalog.Npcs[1].position)<100/64f;}}
        public bool ResetStats(){if(!CanReset||Player.gold<80||Player.statPoints==2*Player.level)return false;foreach(string k in StatKeys)SetStat(k,0);Player.statPoints=2*Player.level;Player.gold-=80;RecomputeStats(false);ScaleSummons(0);return true;}
        public bool LearnSkill(string id){PlayerState p=Player;if(p.skillPoints<1)return false;int rank=id=="q"?p.qRank:id=="e"?p.eRank:id=="r"?p.rRank:id=="passive"?p.passiveRank:3;if(rank>=3)return false;p.skillPoints--;if(id=="q")p.qRank++;if(id=="e")p.eRank++;if(id=="r")p.rRank++;if(id=="passive")p.passiveRank++;Emit("save","");return true;}
        public static float NextXp(int level){return level==1?220:(float)Math.Floor(220*Math.Pow(level,1.68)+level*110);}
        void Xp(int amount){if(amount<=0)return;PlayerState p=Player;p.xp+=amount;while(p.xp>=p.nextXp&&p.level<200){p.xp-=p.nextXp;p.level++;p.statPoints+=2;p.skillPoints++;p.nextXp=NextXp(p.level);RecomputeStats();p.hp=Math.Min(p.maxHp,p.hp+45);p.mp=p.maxMp;PendingLevels=0;Fx("level",p.position,1.5f,"#ffe4a0",1.4f);Emit("level","✦ THĂNG CẤP "+p.level+"! +2 Điểm Chỉ Số (I) & +1 Điểm Kỹ Năng (K)");}}
        float Timer(string id){RelicTimer t=Rpg.timers.Find(x=>x.id==id);return t==null?0:t.left;}
        void Timer(string id,float n){RelicTimer t=Rpg.timers.Find(x=>x.id==id);if(t==null){t=new RelicTimer{id=id};Rpg.timers.Add(t);}t.left=n;}
        float Proc(float chance){return Math.Min(1,chance*(1+Player.lck*.035f));}
        void HealAmount(float n){if(n>0)Player.hp=Math.Min(Player.maxHp,Player.hp+n*(recoveryDepth>0?1:Recovery));}
        void AsDamage(string kind,Action action){string old=damageClass;damageClass=kind;try{action();}finally{damageClass=old;}}
        static V2 At(float x,float y){return new V2(x/64,80-y/64);}
        public int TruthStage {get{return Rpg.chapter>=6?4:Shrines.TrueForAll(s=>s.active)&&BossStarted?3:Shrines.Exists(s=>s.active)||Player.relics.Count>0?2:1;}}
        public void SpawnRelic(string id,V2 at){if(Content.Relic(id)==null||Player.Has(id)||WorldRelics.Exists(r=>r.relic==id))return;WorldRelics.Add(new WorldRelic{relic=id,position=at,drop=true,z=.15f,vz=3.44f,vx=Random(-.7f,.7f)});}
        bool ClaimRelic(WorldRelic r){if(r.claimed||r.drop&&!r.landed||!string.IsNullOrEmpty(r.puzzle)&&!r.unlocked||Enemies.Exists(e=>e.alive&&e.relicGuard==r.relic)||Player.Has(r.relic))return false;r.claimed=true;Player.relics.Add(r.relic);RecomputeStats();Emit("relic",r.relic);Emit("save","");return true;}
        void UnlockRelics(string element,V2 at,float radius){foreach(WorldRelic r in WorldRelics)if(!r.drop&&!r.unlocked&&r.puzzle==element&&V2.Distance(r.position,at)<radius+.55f){r.unlocked=true;Xp(180);Emit("toast","Phong ấn đã mở · "+Content.Relic(r.relic).name);}}
        void GenerateRpg(){
            Props.Clear();Enemies.Clear();Drops.Clear();Shrines.Clear();WorldRelics=new List<WorldRelic>(RpgCatalog.Pedestals());Player.position=Home;
            Shrines.Add(new Shrine{id="truc",name="Ấn Trúc",kind="hunt",position=At(820,700)});Shrines.Add(new Shrine{id="sen",name="Ấn Sen",kind="defend",position=At(3100,2090)});Shrines.Add(new Shrine{id="tro",name="Ấn Tro",kind="forge",position=At(3090,690)});
            for(int i=0;i<1100;i++){V2 p=new V2(Random(1,99),Random(1,69));string z=Zone(p);if(OnPath(p)||V2.Distance(p,Altar)<3||V2.Distance(p,Home)<4||Array.Exists(RpgCatalog.Npcs,n=>V2.Distance(n.position,p)<1.4f)||Array.Exists(RpgCatalog.Memories,m=>V2.Distance(m.position,p)<1.5f)||WorldRelics.Exists(r=>V2.Distance(r.position,p)<2)||Shrines.Exists(s=>V2.Distance(s.position,p)<4))continue;Props.Add(new Prop{position=p,zone=z,type=z=="forest"?"bamboo":z=="lotus"?"willow":z=="ash"||z=="ruins"?"rock":"tree",radius=.3f,variant=Rng.Next(4)});}
            Props.Add(new Prop{position=At(1830,460),type="banyan",zone="ancient",radius=1});Props.Add(new Prop{position=At(550,2200),type="house",zone="village",radius=.7f});Props.Add(new Prop{position=At(860,2100),type="house",zone="village",radius=.7f});Props.Add(new Prop{position=At(650,1940),type="temple",zone="village",radius=.7f});
            for(int i=0;i<180;i++){V2 at=new V2(Random(2,98),Random(2,68));if(Zone(at)=="village"||Collides(at,.4f)||Shrines.Exists(s=>V2.Distance(s.position,at)<4))continue;Spawn(new[]{"slime","wisp","archer","shade","boar"}[i%5],at,false);}
            string[] ids={"giong","kimquy","mjolnir","wukong","phoenix"};float[] xs={914,4780,5570,1210,3180},ys={700,1570,2990,1220,420};foreach(string id in ids){int i=Array.IndexOf(ids,id);RelicDef def=Content.Relic(id);Props.RemoveAll(p=>V2.Distance(p.position,At(xs[i],ys[i]))<2.5f);EnemyState b=Spawn(i==0||i==1?"boar":i==4?"wisp":"shade",At(xs[i],ys[i]),true);b.relic=id;b.name=def.boss;b.miniBoss=true;b.hp=b.maxHp=950+Cycle*190;b.radius=.4f;b.damage=18;if(i==0)Shrines[0].enemies.Add(b.id);}
            foreach(WorldRelic r in WorldRelics)for(int i=0;i<r.guardCount;i++){EnemyState e=Spawn(i%2==0?"shade":"archer",r.position+V2.Angle(i*Mathx.Tau/r.guardCount)*1.7f,true);e.relicGuard=r.relic;e.hp=e.maxHp=160;}
            for(int i=0;i<22;i++){V2 p=i==0?Home+new V2(1.4f,0):new V2(Random(3,97),Random(3,67));if(!Collides(p,.4f))Drops.Add(new Loot{id="chest-"+i,kind="chest",position=p,weapon="lantern"});}
            for(int i=0;i<6;i++)for(int j=0;j<25;j++){V2 p=RpgCatalog.Chapters[i].position+V2.Angle(j*Mathx.Tau/25)*Random(4.8f,7);Props.Add(new Prop{position=p,zone=i==4?"ruins":"forest",type=i==4?"pillar":i==2?"rock":"tree",radius=.35f,variant=j%4});}
            RecomputeStats(false);
        }
        public bool Fire(){string old=damageClass;damageClass="normal";bool ok;try{ok=FireCore();}finally{damageClass=old;}if(!ok)return false;Player.fireTimer/=AttackSpeed;Rpg.attackCount++;EnsureSplit();V2 end=Player.position+V2.Angle(Player.facing)*340/64f;if(Player.Has("giong")&&Rpg.attackCount%4==0)AsDamage("normal",delegate{foreach(EnemyState e in Enemies.ToArray())if(e.alive&&Segment(e.position,Player.position,end)<.31f+e.radius){DamageEnemy(e,Player.damage*2.2f,false);e.stunned=.6f;}Beam(Player.position,end,"#eac77c");});if(Player.Has("mjolnir")&&Rpg.attackCount%5==0){EnemyState e=Nearest(Input.aim,8);if(e!=null){AsDamage("normal",delegate{Area(e.position,120/64f,Player.damage*1.3f,false);Chain(e,Player.damage*1.3f,4);});}}return true;}
        void EnsureSplit(){if(!Player.Has("split"))return;foreach(Bullet b in Bullets.ToArray())if(b.friendly&&!b.splitCreated){b.splitCreated=true;float a=Mathx.Angle(b.velocity)+.11f;Bullets.Add(new Bullet{position=b.position,velocity=V2.Angle(a)*b.velocity.Length,damage=b.damage*.85f,life=b.life,radius=b.radius,pierce=b.pierce,friendly=true,charge=b.charge,kind=b.kind,color=b.color,effect=b.effect,element=b.element,owner=b.owner,returning=b.returning,shadowPoison=b.shadowPoison,damageClass=b.damageClass,splitCreated=true,attackNumber=b.attackNumber});}}
        public void DamageEnemy(EnemyState e,float amount,bool charge){
            if(e==null||!e.alive||float.IsNaN(amount)||float.IsInfinity(amount)||amount<=0)return;PlayerState p=Player;bool burning=e.burn>0,controlled=burning||e.stunned>0||e.frozen>0||e.rooted>0||e.slow>0;float hp=e.hp,m=damageClass=="normal"?1+p.str*.035f:damageClass=="summon"?Dominion:damageClass=="true"?1:1+p.intel*.042f;if(e.miniBoss||e.type=="boss"||e.elite)m*=1+p.fer*.035f;if(p.Has("power"))m*=1.18f;if(Timer("phoenix")>0)m*=1.25f;if(Timer("ankh")>0)m*=1.15f;if(Rpg.questComplete)m*=1.1f;if(damageClass!="true")m*=1-Math.Min(.9f,e.armor*(e.armorShred>0?.75f:1)*(1-Math.Min(1,p.dex*.03f)));if(damageClass=="q"&&Rpg.crystalBoost>0)m*=1+Rpg.crystalBoost;
            e.xp=e.root||e.challenge!=null?0:e.type=="boss"?1000:e.miniBoss?Math.Min(1200,500+Math.Max(0,e.saga)*120):(int)Math.Round((e.type=="slime"?8:e.type=="wisp"?10:e.type=="archer"?14:e.type=="shade"?16:20)*(e.elite?2.8f:1));DamageEnemyCore(e,amount*m,charge);float dealt=Math.Min(hp,Math.Max(0,hp-e.hp));HealAmount(dealt*Omnivamp);if(p.Has("wildfire")){e.burn=Math.Max(e.burn,2.3f);e.burnTick=0;}if(damageClass!="normal"&&damageClass!="true"&&p.Has("hermes"))p.dashTimer=Math.Max(0,p.dashTimer-.4f);
            if(e.alive)return;HealAmount(p.vamp*3+(p.Has("vampire")?(burning||e.shadowBleed>0?12:6):0));Rpg.kills++;if(p.Has("antiem")&&Rpg.kills%6==0)Drops.Add(new Loot{id="melon-"+Kills,kind="melon",position=e.position});if(p.Has("ankh")&&controlled){HealAmount(p.maxHp*.05f);Timer("ankh",4);}if(p.Has("wildfire")&&burning&&!exploding){exploding=true;try{Area(e.position,160/64f,p.damage*1.4f,false);}finally{exploding=false;}}if(e.miniBoss||e.type=="boss"){if(e.name!=null&&!Rpg.bosses.Contains(e.name))Rpg.bosses.Add(e.name);if(e.relic=="giong"&&!Rpg.bosses.Contains("Trúc Vệ"))Rpg.bosses.Add("Trúc Vệ");if(e.relic!=null)SpawnRelic(e.relic,e.position);}if(e.duel)Rpg.duelWon=true;if(Rng.NextDouble()<.14*p.lck*.04f)Drops.Add(new Loot{id="luck-"+Kills,kind=Rng.Next(2)==0?"potion":"mana",position=e.position});AdvanceQuest(null);
        }
        void ElementPrimary(string id,CloneState actor,V2 target,float power,bool charge){AsDamage(actor==null?"normal":"summon",delegate{int count=Bullets.Count;ElementPrimaryCore(id,actor,target,power,charge);if(actor==null&&Player.Has("split")&&Bullets.Count==count)Shoot(Player.position,Mathx.Angle(target-Player.position),11,power*.85f,true,"arrow",Element(id).color);});}
        public void CastElement(string id,string key,CloneState actor,V2 target,bool charge=false,float scale=1){AsDamage(actor==null?key:"summon",delegate{CastElementCore(id,key,actor,target,charge,scale);});}
        int ShadowArea(ShadowUnit s,V2 at,float pixels,float multiplier,string status=null,string terrain=null){int hits=0;AsDamage(s.id==null?"skill":"summon",delegate{hits=ShadowAreaCore(s,at,pixels*Reach,multiplier,status,terrain);});return hits;}
        void ReleaseShadowAttack(ShadowUnit s,EnemyState e){AsDamage("summon",delegate{ReleaseShadowAttackCore(s,e);});}
        void UpdateSummons(float dt){AsDamage("summon",delegate{UpdateSummonsCore(dt);});}
        void UpdateSatellites(float dt){AsDamage("summon",delegate{UpdateSatellitesCore(dt);});}
        void Chain(EnemyState from,float amount,int count){HashSet<string> seen=new HashSet<string>();seen.Add(from.id);for(int i=0;i<count;i++){EnemyState next=null;float range=220/64f;foreach(EnemyState e in Enemies)if(e.alive&&!seen.Contains(e.id)&&V2.Distance(e.position,from.position)<range){next=e;range=V2.Distance(e.position,from.position);}if(next==null)break;Beam(from.position,next.position,"#c9c8ff");seen.Add(next.id);DamageEnemy(next,amount,false);from=next;}}
        bool BeforePlayerDamage(ref float amount){PlayerState p=Player;if(Dead||p.invulnerable>0||amount<=0||Zone(p.position)=="village")return false;EnemyState e=incoming??Nearest(p.position,1);bool melee=e!=null&&V2.Distance(e.position,p.position)<e.radius+.7f;if(e!=null&&e.weakened>0)amount*=.7f;if(p.Has("kimquy")&&Timer("kimquy")<=0){Timer("kimquy",10);p.shield+=(35+p.maxHp*.15f)*Recovery;float a=e==null?p.facing:Mathx.Angle(e.position-p.position);AsDamage("skill",delegate{for(int i=-1;i<=1;i++)Shoot(p.position,a+i*.12f,13.4f,p.damage*2.4f,true,"arrow","#ffe6a6",12);});}if(p.Has("sontinh")&&Timer("sontinh")<=0){amount*=.75f;Timer("sontinh",6);if(melee)StonePillars();}amount=Math.Max(1,amount-p.def*4);Timer("aegisRest",7);if(melee&&p.def>0){float reflect=amount*p.def*.15f;AsDamage("true",delegate{DamageEnemy(e,reflect,false);});p.position=Move(p.position,(p.position-e.position).Unit*(12/64f)/(1+p.str*.04f),.2f);}return true;}
        bool RescueCuoi(float damage){PlayerState p=Player;if(!p.Has("cuoi")||Timer("cuoi")>0||damage<p.hp)return false;p.hp=p.maxHp*.6f;p.mp=p.maxMp;p.frostSlow=p.rooted=p.frozen=p.stunned=0;p.invulnerable=3;Timer("cuoi",180);foreach(EnemyState t in Enemies)if(t.alive&&V2.Distance(t.position,p.position)<250/64f)t.position=MoveEnemy(t,(t.position-p.position).Unit*2.5f,t.radius);return true;}
        void AfterPlayerDamage(){if(aegis&&Player.shield<=0){aegis=false;foreach(EnemyState e in Enemies)if(e.alive&&V2.Distance(e.position,Player.position)<160/64f*Reach)e.stunned=1.2f;}}
        public bool Dash(){bool free=Player.Has("hermes")&&Timer("hermesFree")>0;if(free)Player.dashTimer=0;V2 old=Player.position;if(!DashCore())return false;dashStart=old;Player.dashTimer*=Math.Max(.1f,1-Player.agi*.025f);if(Player.Has("hermes")){Timer("hermesFree",free?0:1.5f);if(!free)hermesCooldown=Player.dashTimer;else Player.dashTimer=hermesCooldown;}if(Player.Has("tam")){AddRelicField("decoy",old,300/64f,2.5f,0);Timer("tam",2.5f);}if(Player.Has("wukong"))MonkeyAllies();if(Player.Has("ariadne")&&Player.hp<Player.maxHp*.35f)Player.invulnerable=Math.Max(.5f,Player.invulnerable);if(Player.Has("dashshock"))RelicShock(old);return true;}
        void RelicShock(V2 at){Area(at,110/64f,Player.damage*1.8f,false);foreach(EnemyState e in Enemies)if(e.alive&&V2.Distance(e.position,at)<110/64f*Reach)e.stunned=.8f;}
        void StonePillars(){EnemyState e=Nearest(Player.position,7.5f);if(e==null)return;for(int i=-1;i<=1;i++)Area(e.position+new V2(i*44/64f,0),38/64f,Player.damage*1.9f,false);}
        void MonkeyAllies(){if(Timer("wukong")>0)return;Timer("wukong",8);for(int i=0;i<2;i++)Rpg.allies.Add(new RelicAlly{position=Player.position+new V2(i==0?-.5f:.5f,0),hp=60*SummonHaste,maxHp=60*SummonHaste,life=4*SummonDuration,dom=Player.dom});}
        void AddRelicField(string kind,V2 at,float radius,float life,float power,bool follow=false){RelicFields.Add(new RelicField{kind=kind,position=at,radius=radius*Reach,life=life,power=power,follow=follow});}
        void RelicCast(string key,float cost){PlayerState p=Player;if(p.Has("aegis")&&key!="r"){p.shield=Math.Max(p.shield,30*Recovery);aegis=true;}if(p.Has("sontinh")&&key=="q")StonePillars();if(p.Has("thuytinh")&&key=="q")AddRelicField("water",Input.aim,145/64f,4.5f,p.damage*.2f);if(p.Has("thachsan")&&key=="e"&&Timer("thachsan")<=0){Timer("thachsan",9);foreach(EnemyState e in Enemies)if(e.alive&&V2.Distance(e.position,p.position)<280/64f*Reach){if(e.miniBoss||e.type=="boss"){e.weakened=2;e.slow=2;}else e.stunned=2.2f;}}if(p.Has("wukong")&&key=="e")MonkeyAllies();if(p.Has("phoenix")&&key=="r"){HealAmount(p.maxHp*.18f);Timer("phoenix",6);AddRelicField("phoenix",p.position,240/64f,6,p.damage*.45f,true);}if(p.Has("cooling"))foreach(EnemyState e in Enemies)if(e.alive&&V2.Distance(e.position,p.position)<180/64f*Reach)e.slow=2;if(p.Has("aladdin")){Rpg.spentMp+=cost;while(Rpg.spentMp>=80){Rpg.spentMp-=80;p.mp=Math.Min(p.maxMp,p.mp+30);V2 end=p.position+V2.Angle(p.facing)*12.5f;foreach(EnemyState e in Enemies.ToArray())if(e.alive&&Segment(e.position,p.position,end)<.47f+e.radius)DamageEnemy(e,p.damage*2.8f,false);Beam(p.position,end,"#a7d5ff");}}}
        void RelicInteract(){if(!Player.Has("chudong"))return;HealAmount(Player.maxHp*.15f);Player.mp=Math.Min(Player.maxMp,Player.mp+20);Timer("castle",5);Fx("ring",Player.position,1.6f,"#dec49d",5);}
        public bool Heal(){int n=Player.potions;float hp=Player.hp;if(!HealCore())return false;float gain=Player.hp-hp;Player.hp=Math.Min(Player.maxHp,hp+gain*Recovery*(Player.Has("traucau")?1.3f:1));if(Player.Has("traucau")){Player.shield+=Player.maxHp*.3f*Recovery;if(Rng.NextDouble()<Proc(.35f))Player.potions=n;}return true;}
        public bool Skill(string key){float mp=Player.mp,hp=Player.hp,shield=Player.shield;string old=damageClass;damageClass=key;int shards=key=="q"&&Player.Has("cinderella")?Rpg.crystals:0;Rpg.crystalBoost=shards*.3f;bool ok;recoveryDepth++;try{ok=SkillCore(key);}finally{damageClass=old;recoveryDepth--;}if(!ok)return false;if(recoveryDepth==0){Player.hp=Math.Min(Player.maxHp,hp+Math.Max(0,Player.hp-hp)*Recovery);Player.shield=shield+Math.Max(0,Player.shield-shield)*Recovery;}if(key=="q")Player.qTimer*=1-CooldownReduction;if(key=="e")Player.eTimer*=1-CooldownReduction;if(shards>0){Rpg.crystals=0;for(int i=0;i<shards*4;i++)Shoot(Player.position,i*Mathx.Tau/(shards*4),10,Player.damage*.5f,true,"arrow","#cdefff",1);}RelicCast(key,mp-Player.mp);EnsureSplit();ScaleSummons(0);return true;}
        void ScaleSummons(float dt){float h=SummonHaste,l=SummonDuration;foreach(ShadowUnit s in ShadowArmy){float old=s.rpgDom<0?1:1+s.rpgDom*.06f,life=s.rpgDom<0?1:1+s.rpgDom*.04f;s.hp*=h/old;s.maxHp*=h/old;s.life*=l/life;s.maxLife*=l/life;s.rpgDom=Player.dom;s.attackCd=Math.Max(0,s.attackCd-dt*(h-1));}foreach(CloneState c in Clones){float old=c.rpgDom<0?1:1+c.rpgDom*.06f;c.hp*=h/old;c.maxHp*=h/old;c.rpgDom=Player.dom;c.attackCd=Math.Max(0,c.attackCd-dt*(h-1));}foreach(SummonState s in Summons){float old=s.rpgDom<0?1:1+s.rpgDom*.06f,life=s.rpgDom<0?1:1+s.rpgDom*.04f;s.hp*=h/old;s.maxHp*=h/old;s.life*=l/life;s.maxLife*=l/life;s.rpgDom=Player.dom;s.attackCd=Math.Max(0,s.attackCd-dt*(h-1));}foreach(RelicAlly s in Rpg.allies){float old=1+s.dom*.06f;s.hp*=h/old;s.maxHp*=h/old;s.life*=l/(1+s.dom*.04f);s.dom=Player.dom;}if(SplitTime>0)SplitTime+=dt*(1-1/l);}
        public void Tick(float delta){if(Paused||Dead)return;float dt=Safe(delta,0,.04f),hp=Player.hp,shield=Player.shield,armor=Player.armor,speed=Player.speed,dash=Player.dashTime;ScaleSummons(dt);if(Timer("castle")>0)Player.armor=Math.Min(.65f,armor+.2f);if(Timer("tam")>0)Player.speed*=1.25f;recoveryDepth++;try{TickCore(dt);}finally{Player.armor=armor;Player.speed=speed;recoveryDepth--;}if(Player.hp>hp)Player.hp=Math.Min(Player.maxHp,hp+(Player.hp-hp)*Recovery);if(Player.shield>shield)Player.shield=shield+(Player.shield-shield)*Recovery;RpgUpdate(dt);if(dash>0&&Player.dashTime<=0){if(Player.Has("dashshock"))RelicShock(Player.position);if(Player.Has("ariadne")){AddRelicField("thread",dashStart,22/64f,4,Player.damage*.5f);RelicFields[RelicFields.Count-1].end=Player.position;}}}
        void RpgUpdate(float dt){
            PlayerState p=Player;foreach(RelicTimer t in Rpg.timers)if(t.id!="cuoi"||Nearest(p.position,650/64f)!=null)t.left=Math.Max(0,t.left-dt);HealAmount((p.vit*.7f+(p.Has("dom")?2:0))*dt);p.mp=Math.Min(p.maxMp,p.mp+p.spi*1.4f*dt);motion=p.moving?motion+dt:0;
            foreach(WorldRelic r in WorldRelics)if(r.drop&&!r.landed&&!r.claimed){r.vz-=7.8125f*dt;r.z+=r.vz*dt;V2 next=r.position+new V2(r.vx*dt,0);if(!Collides(next,.18f))r.position=next;if(r.z<=0){r.z=0;r.landed=true;}}
            foreach(EnemyState e in Enemies){e.wet=Math.Max(0,e.wet-dt);e.weakened=Math.Max(0,e.weakened-dt);e.armorShred=Math.Max(0,e.armorShred-dt);}
            foreach(RelicField f in RelicFields){f.life-=dt;f.tick-=dt;if(f.follow)f.position=p.position;if(f.kind=="decoy")foreach(EnemyState e in Enemies)if(e.alive&&!e.miniBoss&&e.type!="boss"&&V2.Distance(e.position,f.position)<f.radius){e.position=MoveEnemy(e,(f.position-e.position).Unit*e.speed*dt,e.radius);e.cooldown=Math.Max(e.cooldown,.3f);}if(f.kind=="water")foreach(EnemyState e in Enemies)if(e.alive&&V2.Distance(e.position,f.position)<f.radius){e.wet=1;e.slow=.6f;e.position=MoveEnemy(e,(f.position-e.position).Unit*35/64f*dt,e.radius);}if(f.tick>0)continue;f.tick=.25f;foreach(EnemyState e in Enemies.ToArray())if(e.alive&&(f.kind=="thread"?Segment(e.position,f.position,f.end)<f.radius+e.radius:V2.Distance(e.position,f.position)<f.radius)){if(f.kind=="thread"){e.armorShred=4;e.slow=1;AsDamage("true",delegate{DamageEnemy(e,f.power*.25f,false);});}if(f.kind=="phoenix"){DamageEnemy(e,f.power*.25f,false);e.burn=1;}}}RelicFields.RemoveAll(f=>f.life<=0);
            if(p.Has("aegis")&&Timer("aegisRest")<=0&&!aegis){p.shield=Math.Max(p.shield,30*Recovery);aegis=true;}if(p.Has("vitality")&&Props.Exists(o=>o.damageStage<3&&Burnable.Contains(o.type)&&V2.Distance(o.position,p.position)<120/64f))HealAmount(2.5f*dt);
            if(p.Has("jack")&&Timer("jack")<=0){List<EnemyState> near=Enemies.FindAll(e=>e.alive&&V2.Distance(e.position,p.position)<650/64f);if(near.Count>0){near.Sort((a,b)=>near.FindAll(e=>V2.Distance(e.position,b.position)<125/64f).Count.CompareTo(near.FindAll(e=>V2.Distance(e.position,a.position)<125/64f).Count));V2 at=near[0].position;Timer("jack",6);foreach(EnemyState e in near)if(V2.Distance(e.position,at)<125/64f){e.rooted=2.2f;DamageEnemy(e,p.damage*.55f,false);HealAmount(p.damage*.1f);}}}
            if(p.Has("dom")&&Timer("dom")<=0){EnemyState e=Nearest(p.position,7.5f);if(e!=null){Timer("dom",4);AsDamage("summon",delegate{DamageEnemy(e,p.damage*1.5f,false);});Beam(p.position+new V2(-.65f,-.35f),e.position,"#ffe4ac");}}
            foreach(RelicAlly a in Rpg.allies){a.life-=dt;a.attackCd-=dt;EnemyState e=Nearest(a.position,9.4f);if(e==null)continue;float d=V2.Distance(e.position,a.position);if(d>.7f)a.position=Move(a.position,(e.position-a.position).Unit*2.8f*dt,.2f);if(d<1.1f&&a.attackCd<=0){a.attackCd=.55f/SummonHaste;AsDamage("summon",delegate{DamageEnemy(e,p.damage*.75f,false);});}if(d<.55f)a.hp-=e.damage*dt;foreach(Bullet b in Bullets)if(!b.friendly&&V2.Distance(b.position,a.position)<.3f){a.hp-=b.damage;b.life=0;}}Rpg.allies.RemoveAll(a=>a.life<=0||a.hp<=0);
            if(p.Has("haste")&&motion>=3)foreach(Bullet b in Bullets)if(!b.friendly&&b.velocity.Length<300/64f&&V2.Distance(b.position,p.position)<120/64f)b.velocity+=(b.position-p.position).Unit*2.5f*dt;
            AdvanceQuest(null);if(Rpg.chapter<6&&Rpg.chapterStage>0&&!Enemies.Exists(e=>e.alive&&e.saga==Rpg.chapter)){SagaChapter c=RpgCatalog.Chapters[Rpg.chapter];if(Rpg.chapterStage<=3)Emit("toast","Đèn vọng đã sáng · F tại "+c.name);else{Rpg.chapter++;Rpg.chapterStage=0;Xp(450);p.gold+=150;p.skillPoints+=2;Emit("dialogue",c.win);}}
        }
        public string NpcDialogue(StoryNpc n){string text=n.chapter<0?n.lines[TruthStage-1]:Rpg.chapter>=6?n.lines[3]:n.chapter>Rpg.chapter?"Hãy nối ngọn đèn trước khi tới chương này.":RpgCatalog.Chapters[n.chapter].intro;QuestStep s=CurrentQuest;if(s!=null&&s.kind=="npc"&&s.target==n.id)text+="\n\n"+s.text;return n.name+"\n\n"+text;}
        void AdvanceQuest(string npc){QuestStep s=CurrentQuest;while(s!=null){bool done=s.kind=="npc"?s.target==npc:s.kind=="memory"?Rpg.memories.Contains(s.target):s.kind=="memories"?s.targets!=null&&Array.TrueForAll(s.targets,id=>Rpg.memories.Contains(id)):s.kind=="kill"?Rpg.bosses.Exists(b=>b.Contains(s.target)):s.kind=="notes"?Rpg.notes==8:s.kind=="duel"?Rpg.duelWon:s.kind=="truth"&&Rpg.returnedMemories;if(!done)break;Rpg.questStage++;Xp(180);npc=null;s=CurrentQuest;}if(s==null&&!Rpg.questComplete){Rpg.questComplete=true;Player.gold+=200;Player.skillPoints+=2;Emit("dialogue",HeroQuest.reward+"\n\n"+HeroQuest.ending+"\n\n+10% sát thương · 200 xu · 2 điểm kỹ năng");}}
        public bool PlayMemoryNote(int note){QuestStep s=CurrentQuest;if(s==null||s.kind!="notes"||V2.Distance(Player.position,At(3100,2185))>100/64f)return false;int[] notes={1,3,2,5,4,6,5,8};Rpg.notes=note==notes[Rpg.notes]?Rpg.notes+1:0;Emit("sound","pickup");AdvanceQuest(null);return true;}
        public V2 QuestTarget(){QuestStep s=CurrentQuest;if(s==null)return !Rpg.returnedMemories?Altar:Rpg.chapter<6?RpgCatalog.Chapters[Rpg.chapter].position:Home;if(s.kind=="npc"){StoryNpc n=Array.Find(RpgCatalog.Npcs,x=>x.id==s.target);if(n!=null)return n.position;}HeroMemory m=Array.Find(RpgCatalog.Memories,x=>x.hero==Hero.id&&!Rpg.memories.Contains(x.id)&&(x.id==s.target||s.targets!=null&&Array.IndexOf(s.targets,x.id)>=0));if(m!=null)return m.position;return s.kind=="notes"?At(3100,2185):s.kind=="kill"?Shrines[0].position:s.kind=="duel"?At(1830,760):Altar;}
        bool TryRpgInteract(out bool handled){
            handled=true;V2 p=Player.position;WorldRelic tool=WorldRelics.Find(x=>!x.claimed&&!x.unlocked&&!string.IsNullOrEmpty(x.puzzle)&&V2.Distance(x.position+new V2(66/64f,-45/64f),p)<.6f);if(tool!=null){UnlockRelics(tool.puzzle,tool.position,1);return true;}WorldRelic r=WorldRelics.Find(x=>!x.claimed&&V2.Distance(x.position,p)<82/64f);if(r!=null){if(!ClaimRelic(r))Emit("toast",!string.IsNullOrEmpty(r.puzzle)&&!r.unlocked?"Dùng công cụ F ở cạnh bệ để mở phong ấn.":"Hạ hết hộ vệ; đợi vật rơi chạm đất.");return true;}
            r=WorldRelics.Find(x=>!x.claimed&&!x.unlocked&&x.puzzle!=""&&V2.Distance(x.position+new V2(66/64f,-45/64f),p)<.75f);if(r!=null){UnlockRelics(r.puzzle,r.position,1);return true;}
            QuestStep s=CurrentQuest;HeroMemory m=Array.Find(RpgCatalog.Memories,x=>x.hero==Hero.id&&!Rpg.memories.Contains(x.id)&&s!=null&&(s.target==x.id||Array.IndexOf(s.targets,x.id)>=0)&&V2.Distance(x.position,p)<74/64f);if(m!=null){if(m.element!=""&&Player.element!=m.element){Emit("toast","Đài cần dạng "+Element(m.element).name);return false;}Rpg.memories.Add(m.id);Emit("dialogue",m.name+"\n\n"+m.text);AdvanceQuest(null);return true;}
            if(s!=null&&s.kind=="notes"&&V2.Distance(p,At(3100,2185))<1.5f){Emit("melody","");return true;}
            if(s!=null&&s.kind=="duel"&&V2.Distance(p,At(1830,760))<1.5f){if(!Enemies.Exists(e=>e.alive&&e.duel)){EnemyState e=Spawn("shade",At(1830,760),true);e.duel=true;e.hp=e.maxHp=900+Player.level*80;}return true;}
            StoryNpc n=Array.Find(RpgCatalog.Npcs,x=>V2.Distance(x.position,p)<74/64f);if(n!=null){if(n.id=="smith"){Emit("shop","");return true;}if(!Rpg.met.Contains(n.id))Rpg.met.Add(n.id);Emit("dialogue",NpcDialogue(n));AdvanceQuest(n.id);return true;}
            foreach(SagaChapter previous in RpgCatalog.Chapters)if(Array.IndexOf(RpgCatalog.Chapters,previous)<Rpg.chapter&&V2.Distance(p,previous.position)<1.5f){Player.position=Rpg.chapter<6?RpgCatalog.Chapters[Rpg.chapter].position:Home;return true;}
            if(V2.Distance(p,Gate)<1.6f){if(!Rpg.returnedMemories){Emit("toast","Trả ký ức ở Cội Đa trước khi vượt chân trời.");return false;}int i=Math.Min(5,Rpg.chapter);Player.position=RpgCatalog.Chapters[i].position+new V2(0,-2);return true;}
            if(Rpg.returnedMemories&&V2.Distance(p,Home)<1.2f){int i=Math.Min(5,Rpg.chapter);Player.position=RpgCatalog.Chapters[i].position+new V2(0,-2);return true;}
            if(Rpg.chapter<6){SagaChapter c=RpgCatalog.Chapters[Rpg.chapter];if(V2.Distance(p,c.position)<1.5f){if(Enemies.Exists(e=>e.alive&&e.saga==Rpg.chapter))return false;if(Rpg.chapterStage<3){int stage=Rpg.chapterStage++;Emit("dialogue",c.echoes[stage]);for(int i=0;i<3+stage;i++){EnemyState e=Spawn(i%2==0?"shade":"archer",c.position+V2.Angle(i*Mathx.Tau/(3+stage))*3,true);e.saga=Rpg.chapter;e.hp=e.maxHp=100+Rpg.chapter*30;}}else{Rpg.chapterStage=4;EnemyState e=Spawn(Rpg.chapter==0?"wisp":"shade",c.position+new V2(0,3),true);e.name=c.boss;e.miniBoss=true;e.saga=Rpg.chapter;e.relic=c.relic;e.hp=e.maxHp=1400+Rpg.chapter*350;}return true;}}
            if(V2.Distance(p,Altar)<1.5f&&Victory){if(!Rpg.returnedMemories){Rpg.returnedMemories=true;Xp(450);}Emit("dialogue",RpgCatalog.TruthReturn);AdvanceQuest(null);return true;}
            handled=false;return false;
        }
        public bool Interact(){if(Paused||Dead)return false;bool handled;bool ok=TryRpgInteract(out handled);if(!handled)ok=InteractCore();if(ok)RelicInteract();return ok;}
        public string Objective(){QuestStep step=CurrentQuest;return step!=null?Hero.name+" · "+step.title+"\n"+step.hint:Rpg.chapter<6?"Trả ký ức về Cội Đa, rồi nối sáu ngọn đèn bên kia chân trời.":"Làng Đèn đã nhớ. Đốm là trái tim hy vọng được gửi ngược về.";}
        public string Nearby(){V2 p=Player.position;WorldRelic r=WorldRelics.Find(x=>!x.claimed&&!x.unlocked&&!string.IsNullOrEmpty(x.puzzle)&&V2.Distance(x.position+new V2(66/64f,-45/64f),p)<.75f);if(r!=null)return "F · Công cụ mở phong ấn "+r.puzzle;r=WorldRelics.Find(x=>!x.claimed&&V2.Distance(x.position,p)<82/64f);if(r!=null)return "F · "+Content.Relic(r.relic).name;StoryNpc n=Array.Find(RpgCatalog.Npcs,x=>V2.Distance(x.position,p)<74/64f);if(n!=null)return "F · "+n.name;if(V2.Distance(QuestTarget(),p)<1.5f&&CurrentQuest!=null)return "F · "+CurrentQuest.title;if(V2.Distance(p,Gate)<1.5f)return "F · Vượt chân trời";if(Rpg.chapter<6&&V2.Distance(p,RpgCatalog.Chapters[Rpg.chapter].position)<1.5f)return "F · Nối đèn vọng / gọi thủ lĩnh";return NearbyCore();}
        void RestoreRpg(RunSave data){Rpg=data.rpg??new RpgProgress();Rpg.met=Rpg.met??new List<string>();Rpg.memories=Rpg.memories??new List<string>();Rpg.bosses=Rpg.bosses??new List<string>();Rpg.timers=Rpg.timers??new List<RelicTimer>();Rpg.allies=Rpg.allies??new List<RelicAlly>();Rpg.timers.RemoveAll(t=>t==null||string.IsNullOrEmpty(t.id));foreach(RelicTimer t in Rpg.timers)t.left=Safe(t.left,0,180);Rpg.allies.RemoveAll(t=>t==null||t.life<=0||t.hp<=0||float.IsNaN(t.hp)||float.IsInfinity(t.hp)||float.IsNaN(t.life)||float.IsInfinity(t.life));if(Rpg.allies.Count>2)Rpg.allies.RemoveRange(2,Rpg.allies.Count-2);Rpg.chapterStage=(int)Safe(Rpg.chapterStage,0,4);Rpg.met.RemoveAll(string.IsNullOrEmpty);Rpg.memories.RemoveAll(string.IsNullOrEmpty);Rpg.bosses.RemoveAll(string.IsNullOrEmpty);foreach(RelicAlly ally in Rpg.allies){ally.dom=(int)Safe(ally.dom,0,199);ally.maxHp=Safe(ally.maxHp,1,50000);ally.hp=Safe(ally.hp,1,ally.maxHp);ally.life=Safe(ally.life,0,300);ally.position=new V2(Safe(ally.position.x,1,Width-1,Player.position.x),Safe(ally.position.y,1,Height-1,Player.position.y));}Rpg.trainingHp=(int)Safe(Rpg.trainingHp,0,400);Rpg.trainingDamage=(int)Safe(Rpg.trainingDamage,0,400);Rpg.chapter=(int)Safe(Rpg.chapter,0,6);Rpg.questStage=(int)Safe(Rpg.questStage,0,HeroQuest.steps.Length);Rpg.notes=(int)Safe(Rpg.notes,0,8);Player.level=(int)Safe(Player.level,1,200,1);int left=2*Player.level;foreach(string k in StatKeys){int n=(int)Safe(Stat(k),0,Math.Min(199,left));SetStat(k,n);left-=n;}Player.statPoints=left;PendingLevels=0;Player.skillPoints=(int)Safe(Player.skillPoints,0,999,3);RecomputeStats(false);Player.nextXp=NextXp(Player.level);Player.xp=Safe(Player.xp,0,Player.nextXp-1);if(data.worldRelics!=null){WorldRelics=new List<WorldRelic>(RpgCatalog.Pedestals());foreach(WorldRelic r in data.worldRelics){if(r==null||Content.Relic(r.relic)==null||float.IsNaN(r.position.x)||float.IsNaN(r.position.y)||float.IsInfinity(r.position.x)||float.IsInfinity(r.position.y))continue;WorldRelic p=WorldRelics.Find(x=>x.relic==r.relic);if(p!=null){p.claimed=r.claimed||Player.Has(r.relic);p.unlocked=r.unlocked;}else if(r.drop&&!r.claimed&&!Player.Has(r.relic)){r.z=0;r.landed=true;WorldRelics.Add(r);}}}if(data.rpg==null){Player.position=Home;Rpg.returnedMemories=Victory;Emit("toast","Bản lưu cũ chuyển sang chỉ số RPG; điểm chưa dùng đã được hoàn.");}foreach(EnemyState e in Enemies)if(!e.alive&&e.relic!=null&&!Player.Has(e.relic))SpawnRelic(e.relic,e.position);}
    }
}
